  function finishChallenge(i){const checks=state.challengeChecks[i]||[],checked=checks.length===challenges[i].steps.length&&checks.every(Boolean),solved=(state.challengeOrderSolved||[]).includes(i);if(checked&&solved&&!(state.challengeAwarded||[]).includes(i)){state.challengeAwarded.push(i);state.xp+=25;toast('Tantangan selesai! +25 XP!');if(i===4)addBadge('team','Kolaborator');save();renderChallenges()}}
  function renderGlossary(query=''){const q=query.toLowerCase();const items=glossary.filter(([a,b])=>(a+' '+b).toLowerCase().includes(q));$('#glossaryGrid').innerHTML=items.length?items.map(([a,b])=>`<article class="glossary-item"><strong>${a}</strong><p>${b}</p></article>`).join(''):'<p>Belum ada istilah yang cocok. Coba kata lain.</p>';const questions=faqs.filter(([a,b])=>(a+' '+b).toLowerCase().includes(q));$('#faqGrid').innerHTML='<h3>Pertanyaan yang sering ditanyakan</h3>'+questions.map(([a,b])=>`<details><summary>${a}</summary><p>${b}</p></details>`).join('')}
  $('#glossarySearch').oninput=e=>renderGlossary(e.target.value);$('#resetProgress').onclick=()=>{if(confirm('Yakin ingin menghapus semua progres, XP, badge, dan skor tersimpan di perangkat ini?')){state=defaultState();save();lessonIndex=0;renderLesson();renderChallenges();renderFlash();qIndex=0;qScore=0;qAnswered=false;renderQuiz();toast('Progres berhasil direset.')}};
  const nav=$('#mainNav'),menu=$('#menuToggle');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))};$$('#mainNav a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')});
  function celebrate(el){if(!el)return;el.classList.remove('success-pop');void el.offsetWidth;el.classList.add('success-pop');if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect(),burst=document.createElement('span');burst.className='celebrate-burst';burst.setAttribute('aria-hidden','true');burst.style.left=Math.max(12,Math.min(innerWidth-12,r.left+r.width/2))+'px';burst.style.top=Math.max(12,Math.min(innerHeight-12,r.top+r.height/2))+'px';const colors=['#df9f42','#72ad7a','#6389da','#e58570','#b48bd3'];for(let i=0;i<14;i++){const p=document.createElement('i'),angle=(Math.PI*2*i)/14,distance=32+Math.random()*38;p.style.setProperty('--dx',Math.cos(angle)*distance+'px');p.style.setProperty('--dy',Math.sin(angle)*distance+'px');p.style.setProperty('--color',colors[i%colors.length]);p.style.setProperty('--delay',Math.random()*.09+'s');burst.append(p)}document.body.append(burst);setTimeout(()=>burst.remove(),1000)}
  document.addEventListener('click',e=>{const answer=e.target.closest('[data-answer]');if(answer){setTimeout(()=>{if(answer.classList.contains('correct'))celebrate(answer);else if(answer.classList.contains('incorrect'))answer.classList.add('gentle-shake')},0);return}const check=e.target.closest('#checkLesson');if(check){setTimeout(()=>{const fb=$('#lessonFeedback');if(fb&&fb.textContent.startsWith('Benar!'))celebrate(check.closest('.practice-box'))},0);return}const pr=e.target.closest('[data-pr="merge"],[data-conflict]');if(pr){setTimeout(()=>celebrate(pr.closest('.practice-box')),0)}});
